class Solution {
    List<String> res = new ArrayList<>();
    public List<String> generateParenthesis(int n) {
        backtrack("",0,0,n);
        return res;
    }
    private void backtrack(String str, int left, int right, int n){
        if(str.length() == 2*n){
            res.add(str);
            return;
        }
        if(left < n) backtrack(str+"(",left+1,right,n);
        if(right < left) backtrack(str+")",left,right+1,n);
    }
}
